-- Reporting views for the ODAG1 sampling dashboard (Tableau). Create by hand in HSLABBOSS, in this order.
-- Needs Teradata 16.20 or later (TRYCAST). V_SMPL_DSH_DQ reads V_SMPL_DSH_UNIVERSE.

-- V_SMPL_DSH_UNIVERSE: Universe: every current ODAG1 row with its functional area, determination, flags, data checks and what the sample did with it
REPLACE VIEW HSLABBOSS.V_SMPL_DSH_UNIVERSE AS
LOCKING ROW FOR ACCESS
SELECT d.*, CASE WHEN d.Determination IN ('Missing', 'Other') THEN 1 ELSE 0 END AS DQ_Missing_Determination, CASE WHEN d.Functional_Area = 'OTHER' THEN 1 ELSE 0 END AS DQ_No_Functional_Area, CASE WHEN d.CPT_List IS NULL THEN 1 ELSE 0 END AS DQ_Missing_CPT, CASE WHEN d.Network = 'Unknown' THEN 1 ELSE 0 END AS DQ_Bad_Provider_Type, CASE WHEN d.Processing = 'Unknown' THEN 1 ELSE 0 END AS DQ_Bad_Processing_Ind, CASE WHEN d.Request_Dt IS NULL THEN 1 ELSE 0 END AS DQ_Bad_Request_Date, CASE WHEN d.Determination_Dt IS NULL AND d.Determination <> 'Missing' THEN 1 ELSE 0 END AS DQ_Bad_Determination_Date, CASE WHEN d.Decision_Days < 0 THEN 1 ELSE 0 END AS DQ_Notice_Before_Request, CASE WHEN d.Determination = 'Denied' AND COALESCE(TRIM(d.REQ_DENY_FOR_LACK_OF_MED_NECTY_IND), '') = '' THEN 1 ELSE 0 END AS DQ_Denial_Missing_MedNec, CASE WHEN d.Determination = 'Denied' AND COALESCE(TRIM(d.MBR_WRTN_NOTFTN_DT), '') = '' THEN 1 ELSE 0 END AS DQ_Denial_Missing_Written_Notice, CASE WHEN d.Key_Row_Cnt > 1 THEN 1 ELSE 0 END AS DQ_Duplicate_Key, (DQ_Missing_Determination + DQ_No_Functional_Area + DQ_Missing_CPT + DQ_Bad_Provider_Type + DQ_Bad_Processing_Ind + DQ_Bad_Request_Date + DQ_Bad_Determination_Date + DQ_Notice_Before_Request + DQ_Denial_Missing_MedNec + DQ_Denial_Missing_Written_Notice + DQ_Duplicate_Key) AS DQ_Issue_Cnt, CASE WHEN x.Case_Key IS NULL THEN 'Not sampled' WHEN x.Excluded_Ind = 1 THEN 'Excluded' WHEN x.Selected_Ind = 1 THEN 'Selected' WHEN x.Selection_Stat = 'REPLACED' THEN 'Replaced' WHEN x.Selection_Stat = 'SKIPPED' THEN 'Skipped' ELSE 'Not selected' END AS Sample_Status, x.Smpl_Run_ID, x.Exclusion_Rsn_Txt, x.Not_Selected_Rsn_Txt, x.Stratum_Path_Txt, x.Selection_Order_Nbr, x.Priority_Rank_Nbr, COALESCE(x.Selected_Ind, 0) AS Selected_Ind, CASE WHEN x.Case_Key IS NULL THEN 'Not sampled' WHEN x.Exclusion_Rsn_Txt = 'SELECTED_IN_LAST_90_DAYS' THEN 'Prior selection' WHEN COALESCE(x.Exclusion_Rsn_Txt, '-') = COALESCE(d.Expected_Exclusion, '-') THEN 'Agrees' ELSE 'Differs' END AS Exclusion_Check FROM (SELECT b.BTCH_ID, b.AUTHZN_ID, b.SRC_DATA_KEY, b.MBR_ID, b.CNTRCT_NUM, b.PBP_NUM, b.FDR_NM, b.AUTHZN_REQ_DT, b.DETRMTN_NOTFTN_DT, b.MBR_WRTN_NOTFTN_DT, b.AUTHZN_REQ_DETRMTN_TY, b.AUTHZN_REQ_STD_OR_EXPDT_IND, b.AUTHZN_REQ_EXPDT_PROCS_STD_IND, b.TIMEFRAME_EXT_IND, b.PART_B_DRUG_REQ_IND, b.REQSTR_TY_CD, b.ISS_DESC, b.REQ_DENY_FOR_LACK_OF_MED_NECTY_IND, b.SVC_CTGRY_CD, b.AUTHZN_STAT_RSN_DESC, b.WTHDRL_DESC, b.REQ_PROV_TY, b.SVC_PROV_TY, b.CPT_PROC_CD, b.RVSN_NBR, b.UNVRS_VRSN_CD, b.FILE_NM, b.Key_Row_Cnt, 'AUTHZN_ID=' || TRIM(TRAILING FROM b.AUTHZN_ID) || '|SRC_DATA_KEY=' || TRIM(CAST(b.SRC_DATA_KEY AS VARCHAR(20))) AS Case_Key, TRYCAST(SUBSTR(b.BTCH_ID, 1, 4) || '-' || SUBSTR(b.BTCH_ID, 5, 2) || '-' || SUBSTR(b.BTCH_ID, 7, 2) AS DATE) AS Batch_Dt, CASE WHEN b.Request_Type = 'Drugs - Biologics Part B' THEN 'Part B' WHEN b.Request_Type LIKE 'Behavioral Health%' OR (b.Request_Type = 'Outpatient' AND b.Type_Detail = 'Behavioral Health') THEN 'BH' WHEN b.Request_Type = 'Outpatient' AND b.Type_Detail LIKE 'Durable Medical Equipment%' THEN 'DME' WHEN b.Request_Type = 'Outpatient' AND b.Type_Detail = 'Home Health Services' THEN 'HHC' WHEN b.Request_Type = 'Inpatient' AND (b.Type_Detail IN ('Rehab', 'LTAC') OR b.Type_Detail LIKE 'SNF%') THEN 'IP PAC' WHEN b.Request_Type = 'Outpatient' THEN 'OP Medical' WHEN b.Request_Type = 'Inpatient' THEN 'IP Medical' ELSE 'OTHER' END AS Functional_Area, CASE CASE WHEN b.Request_Type = 'Drugs - Biologics Part B' THEN 'Part B' WHEN b.Request_Type LIKE 'Behavioral Health%' OR (b.Request_Type = 'Outpatient' AND b.Type_Detail = 'Behavioral Health') THEN 'BH' WHEN b.Request_Type = 'Outpatient' AND b.Type_Detail LIKE 'Durable Medical Equipment%' THEN 'DME' WHEN b.Request_Type = 'Outpatient' AND b.Type_Detail = 'Home Health Services' THEN 'HHC' WHEN b.Request_Type = 'Inpatient' AND (b.Type_Detail IN ('Rehab', 'LTAC') OR b.Type_Detail LIKE 'SNF%') THEN 'IP PAC' WHEN b.Request_Type = 'Outpatient' THEN 'OP Medical' WHEN b.Request_Type = 'Inpatient' THEN 'IP Medical' ELSE 'OTHER' END WHEN 'DME' THEN 'OP PAC' WHEN 'HHC' THEN 'OP PAC' WHEN 'OP Medical' THEN 'Medical' WHEN 'IP Medical' THEN 'Medical' ELSE CASE WHEN b.Request_Type = 'Drugs - Biologics Part B' THEN 'Part B' WHEN b.Request_Type LIKE 'Behavioral Health%' OR (b.Request_Type = 'Outpatient' AND b.Type_Detail = 'Behavioral Health') THEN 'BH' WHEN b.Request_Type = 'Outpatient' AND b.Type_Detail LIKE 'Durable Medical Equipment%' THEN 'DME' WHEN b.Request_Type = 'Outpatient' AND b.Type_Detail = 'Home Health Services' THEN 'HHC' WHEN b.Request_Type = 'Inpatient' AND (b.Type_Detail IN ('Rehab', 'LTAC') OR b.Type_Detail LIKE 'SNF%') THEN 'IP PAC' WHEN b.Request_Type = 'Outpatient' THEN 'OP Medical' WHEN b.Request_Type = 'Inpatient' THEN 'IP Medical' ELSE 'OTHER' END END AS Area_Group, CASE WHEN CASE WHEN b.Request_Type = 'Drugs - Biologics Part B' THEN 'Part B' WHEN b.Request_Type LIKE 'Behavioral Health%' OR (b.Request_Type = 'Outpatient' AND b.Type_Detail = 'Behavioral Health') THEN 'BH' WHEN b.Request_Type = 'Outpatient' AND b.Type_Detail LIKE 'Durable Medical Equipment%' THEN 'DME' WHEN b.Request_Type = 'Outpatient' AND b.Type_Detail = 'Home Health Services' THEN 'HHC' WHEN b.Request_Type = 'Inpatient' AND (b.Type_Detail IN ('Rehab', 'LTAC') OR b.Type_Detail LIKE 'SNF%') THEN 'IP PAC' WHEN b.Request_Type = 'Outpatient' THEN 'OP Medical' WHEN b.Request_Type = 'Inpatient' THEN 'IP Medical' ELSE 'OTHER' END = 'IP PAC' THEN CASE WHEN b.Type_Detail = 'Rehab' THEN 'IPRF' WHEN b.Type_Detail = 'LTAC' THEN 'LTAC' ELSE 'SNF' END END AS IP_PAC_Type, CASE WHEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) = 'Partially Approved' THEN 'Approved' WHEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) IN ('Approved', 'Denied', 'Dismissed') THEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) WHEN COALESCE(TRIM(b.AUTHZN_REQ_DETRMTN_TY), '') = '' THEN 'Missing' ELSE 'Other' END AS Determination, CASE TRIM(b.AUTHZN_REQ_STD_OR_EXPDT_IND) WHEN 'E' THEN 'Expedited' WHEN 'S' THEN 'Standard' ELSE 'Unknown' END AS Processing, CASE WHEN UPPER(TRIM(b.SVC_PROV_TY)) = 'NON PAR' THEN 'Out of network' WHEN UPPER(TRIM(b.SVC_PROV_TY)) = 'PAR' THEN 'In network' ELSE 'Unknown' END AS Network, CASE WHEN UPPER(TRIM(b.SVC_PROV_TY)) = 'NON PAR' THEN 1 ELSE 0 END AS OON_Ind, CASE WHEN CASE WHEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) = 'Partially Approved' THEN 'Approved' WHEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) IN ('Approved', 'Denied', 'Dismissed') THEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) WHEN COALESCE(TRIM(b.AUTHZN_REQ_DETRMTN_TY), '') = '' THEN 'Missing' ELSE 'Other' END = 'Denied' AND UPPER(TRIM(b.REQ_DENY_FOR_LACK_OF_MED_NECTY_IND)) = 'Y' THEN 1 ELSE 0 END AS Med_Necessity_Denial_Ind, NULLIF(OREPLACE(COALESCE(b.CPT_PROC_CD, ''), ' ', ''), '') AS CPT_List, TRIM(STRTOK(NULLIF(OREPLACE(COALESCE(b.CPT_PROC_CD, ''), ' ', ''), ''), ',', 1)) AS CPT_First, CASE WHEN COALESCE(TRIM(b.CPT_PROC_CD), '') = '' THEN 0 ELSE CHARACTER_LENGTH(OREPLACE(b.CPT_PROC_CD, ' ', '')) - CHARACTER_LENGTH(OREPLACE(OREPLACE(b.CPT_PROC_CD, ' ', ''), ',', '')) + 1 END AS CPT_Cnt, COALESCE(sh.Auto_Approved_Ind, 0) AS Shrpa_Auto_Approved_Ind, COALESCE(sh.No_PA_Ind, 0) AS Shrpa_No_PA_Ind, COALESCE(sh.Clinical_Review_Ind, 0) AS Shrpa_Clinical_Review_Ind, CASE WHEN ',' || OREPLACE(COALESCE(b.CPT_PROC_CD, ''), ' ', '') || ',' LIKE ANY ('%,A4233,%', '%,A4234,%', '%,A4235,%', '%,A4236,%', '%,A4238,%', '%,A4239,%', '%,A4244,%', '%,A4245,%', '%,A4246,%', '%,A4247,%', '%,A4250,%', '%,A4253,%', '%,A4255,%', '%,A4256,%', '%,A4257,%', '%,A4258,%', '%,A4259,%', '%,A4271,%', '%,E0607,%', '%,E0784,%', '%,E2100,%', '%,E2101,%', '%,E2102,%', '%,E2103,%', '%,K0552,%') THEN 1 ELSE 0 END AS Diabetic_Supply_Ind, CASE WHEN TRIM(b.RVSN_NBR) = '1' THEN 1 ELSE 0 END AS Initial_Auth_Ind, CASE WHEN COALESCE(sh.Auto_Approved_Ind, 0) = 1 THEN 'AUTO_APPROVED' WHEN COALESCE(sh.No_PA_Ind, 0) = 1 THEN 'NO_PA_REQUIRED' WHEN CASE WHEN ',' || OREPLACE(COALESCE(b.CPT_PROC_CD, ''), ' ', '') || ',' LIKE ANY ('%,A4233,%', '%,A4234,%', '%,A4235,%', '%,A4236,%', '%,A4238,%', '%,A4239,%', '%,A4244,%', '%,A4245,%', '%,A4246,%', '%,A4247,%', '%,A4250,%', '%,A4253,%', '%,A4255,%', '%,A4256,%', '%,A4257,%', '%,A4258,%', '%,A4259,%', '%,A4271,%', '%,E0607,%', '%,E0784,%', '%,E2100,%', '%,E2101,%', '%,E2102,%', '%,E2103,%', '%,K0552,%') THEN 1 ELSE 0 END = 1 THEN 'DIABETIC_SUPPLIES' WHEN COALESCE(TRIM(b.RVSN_NBR), '') <> '1' THEN 'REVISION' END AS Expected_Exclusion, CASE WHEN CASE WHEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) = 'Partially Approved' THEN 'Approved' WHEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) IN ('Approved', 'Denied', 'Dismissed') THEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) WHEN COALESCE(TRIM(b.AUTHZN_REQ_DETRMTN_TY), '') = '' THEN 'Missing' ELSE 'Other' END = 'Denied' THEN 'Yes' WHEN CASE WHEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) = 'Partially Approved' THEN 'Approved' WHEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) IN ('Approved', 'Denied', 'Dismissed') THEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) WHEN COALESCE(TRIM(b.AUTHZN_REQ_DETRMTN_TY), '') = '' THEN 'Missing' ELSE 'Other' END = 'Approved' AND COALESCE(sh.Clinical_Review_Ind, 0) = 1 THEN 'Yes' ELSE 'No' END AS Needs_Clinical_Auditor, CASE WHEN CASE WHEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) = 'Partially Approved' THEN 'Approved' WHEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) IN ('Approved', 'Denied', 'Dismissed') THEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) WHEN COALESCE(TRIM(b.AUTHZN_REQ_DETRMTN_TY), '') = '' THEN 'Missing' ELSE 'Other' END = 'Denied' OR (CASE WHEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) = 'Partially Approved' THEN 'Approved' WHEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) IN ('Approved', 'Denied', 'Dismissed') THEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) WHEN COALESCE(TRIM(b.AUTHZN_REQ_DETRMTN_TY), '') = '' THEN 'Missing' ELSE 'Other' END = 'Approved' AND COALESCE(sh.Clinical_Review_Ind, 0) = 1) THEN 'Clinical' ELSE 'Administrative' END AS Auditor_Type, TRYCAST(OREPLACE(TRIM(b.AUTHZN_REQ_DT), '/', '-') AS DATE) AS Request_Dt, TRYCAST(OREPLACE(TRIM(b.DETRMTN_NOTFTN_DT), '/', '-') AS DATE) AS Determination_Dt, TRYCAST(OREPLACE(TRIM(b.DETRMTN_NOTFTN_DT), '/', '-') AS DATE) - TRYCAST(OREPLACE(TRIM(b.AUTHZN_REQ_DT), '/', '-') AS DATE) AS Decision_Days, 1 AS Case_Cnt, b.Request_Type, b.Type_Detail FROM (SELECT o.BTCH_ID, o.AUTHZN_ID, o.SRC_DATA_KEY, o.MBR_ID, o.CNTRCT_NUM, o.PBP_NUM, o.FDR_NM, o.AUTHZN_REQ_DT, o.DETRMTN_NOTFTN_DT, o.MBR_WRTN_NOTFTN_DT, o.AUTHZN_REQ_DETRMTN_TY, o.AUTHZN_REQ_STD_OR_EXPDT_IND, o.AUTHZN_REQ_EXPDT_PROCS_STD_IND, o.TIMEFRAME_EXT_IND, o.PART_B_DRUG_REQ_IND, o.REQSTR_TY_CD, o.ISS_DESC, o.REQ_DENY_FOR_LACK_OF_MED_NECTY_IND, o.SVC_CTGRY_CD, o.AUTHZN_STAT_RSN_DESC, o.WTHDRL_DESC, o.REQ_PROV_TY, o.SVC_PROV_TY, o.CPT_PROC_CD, o.RVSN_NBR, o.UNVRS_VRSN_CD, o.FILE_NM, TRIM(STRTOK(NULLIF(TRIM(o.ISS_DESC), ''), ',', 1)) AS Request_Type, TRIM(STRTOK(NULLIF(TRIM(o.ISS_DESC), ''), ',', 2)) AS Type_Detail, COUNT(*) OVER (PARTITION BY o.BTCH_ID, o.AUTHZN_ID, o.SRC_DATA_KEY) AS Key_Row_Cnt FROM HSLABBOSS.SDO_CMPLNC_CLNCL_AUD_UM_AUTHZN_ODAG1 o WHERE o.ETL_IS_CURR_IND = 'Y' AND o.ETL_IS_DEL_IND = 'N') b LEFT JOIN (SELECT o2.BTCH_ID, o2.AUTHZN_ID, o2.SRC_DATA_KEY, MAX(CASE WHEN s.IS_Auth_Required LIKE '%approve%' THEN 1 ELSE 0 END) AS Auto_Approved_Ind, MAX(CASE WHEN s.IS_Auth_Required = 'No Auth Required - Check to see if a global rule applies' THEN 1 ELSE 0 END) AS No_PA_Ind, MAX(CASE WHEN COALESCE(TRIM(s.Clinical_Mgt_Route), '') <> '' THEN 1 ELSE 0 END) AS Clinical_Review_Ind FROM HSLABBOSS.SDO_CMPLNC_CLNCL_AUD_UM_AUTHZN_ODAG1 o2 JOIN HSLABBOSS.UMCM_SHRPA_PROCEDURE_CODES s ON POSITION(',' || TRIM(s.PROCEDURE_CODE) || ',' IN ',' || OREPLACE(COALESCE(o2.CPT_PROC_CD, ''), ' ', '') || ',') > 0 AND s.ETL_IS_CURR_IND = 'Y' AND s.ETL_IS_DEL_IND = 'N' WHERE o2.ETL_IS_CURR_IND = 'Y' AND o2.ETL_IS_DEL_IND = 'N' GROUP BY 1, 2, 3) sh ON sh.BTCH_ID = b.BTCH_ID AND sh.AUTHZN_ID = b.AUTHZN_ID AND sh.SRC_DATA_KEY = b.SRC_DATA_KEY) d LEFT JOIN HSLABBOSS.GOVT_RGLTRY_SampleSelection x ON x.Project_Cd = 'UMCM' AND x.Table_Nm = 'ODAG1' AND x.Run_Ty = 'WKLY' AND x.Curr_Ind = 1 AND x.Run_Key = d.BTCH_ID AND x.Case_Key = d.Case_Key;

-- V_SMPL_DSH_DQ: Universe risks and errors: one row per data check a row fails
REPLACE VIEW HSLABBOSS.V_SMPL_DSH_DQ AS
LOCKING ROW FOR ACCESS
SELECT u.BTCH_ID, u.Batch_Dt, u.AUTHZN_ID, u.SRC_DATA_KEY, u.Case_Key, u.Functional_Area, u.Determination, u.Processing, u.Sample_Status, 'Determination missing or not a known value' AS Issue_Txt, 'Error' AS Severity_Txt, 'AUTHZN_REQ_DETRMTN_TY' AS Column_Nm, CAST(u.AUTHZN_REQ_DETRMTN_TY AS VARCHAR(500)) AS Value_Txt, 1 AS Issue_Cnt FROM HSLABBOSS.V_SMPL_DSH_UNIVERSE u WHERE u.DQ_Missing_Determination = 1
UNION ALL
SELECT u.BTCH_ID, u.Batch_Dt, u.AUTHZN_ID, u.SRC_DATA_KEY, u.Case_Key, u.Functional_Area, u.Determination, u.Processing, u.Sample_Status, 'Issue description maps to no functional area' AS Issue_Txt, 'Warning' AS Severity_Txt, 'ISS_DESC' AS Column_Nm, CAST(u.ISS_DESC AS VARCHAR(500)) AS Value_Txt, 1 AS Issue_Cnt FROM HSLABBOSS.V_SMPL_DSH_UNIVERSE u WHERE u.DQ_No_Functional_Area = 1
UNION ALL
SELECT u.BTCH_ID, u.Batch_Dt, u.AUTHZN_ID, u.SRC_DATA_KEY, u.Case_Key, u.Functional_Area, u.Determination, u.Processing, u.Sample_Status, 'No procedure code' AS Issue_Txt, 'Error' AS Severity_Txt, 'CPT_PROC_CD' AS Column_Nm, CAST(u.CPT_PROC_CD AS VARCHAR(500)) AS Value_Txt, 1 AS Issue_Cnt FROM HSLABBOSS.V_SMPL_DSH_UNIVERSE u WHERE u.DQ_Missing_CPT = 1
UNION ALL
SELECT u.BTCH_ID, u.Batch_Dt, u.AUTHZN_ID, u.SRC_DATA_KEY, u.Case_Key, u.Functional_Area, u.Determination, u.Processing, u.Sample_Status, 'Servicing provider type is not PAR or Non par' AS Issue_Txt, 'Warning' AS Severity_Txt, 'SVC_PROV_TY' AS Column_Nm, CAST(u.SVC_PROV_TY AS VARCHAR(500)) AS Value_Txt, 1 AS Issue_Cnt FROM HSLABBOSS.V_SMPL_DSH_UNIVERSE u WHERE u.DQ_Bad_Provider_Type = 1
UNION ALL
SELECT u.BTCH_ID, u.Batch_Dt, u.AUTHZN_ID, u.SRC_DATA_KEY, u.Case_Key, u.Functional_Area, u.Determination, u.Processing, u.Sample_Status, 'Standard / expedited indicator is not S or E' AS Issue_Txt, 'Error' AS Severity_Txt, 'AUTHZN_REQ_STD_OR_EXPDT_IND' AS Column_Nm, CAST(u.AUTHZN_REQ_STD_OR_EXPDT_IND AS VARCHAR(500)) AS Value_Txt, 1 AS Issue_Cnt FROM HSLABBOSS.V_SMPL_DSH_UNIVERSE u WHERE u.DQ_Bad_Processing_Ind = 1
UNION ALL
SELECT u.BTCH_ID, u.Batch_Dt, u.AUTHZN_ID, u.SRC_DATA_KEY, u.Case_Key, u.Functional_Area, u.Determination, u.Processing, u.Sample_Status, 'Request date missing or not a date' AS Issue_Txt, 'Error' AS Severity_Txt, 'AUTHZN_REQ_DT' AS Column_Nm, CAST(u.AUTHZN_REQ_DT AS VARCHAR(500)) AS Value_Txt, 1 AS Issue_Cnt FROM HSLABBOSS.V_SMPL_DSH_UNIVERSE u WHERE u.DQ_Bad_Request_Date = 1
UNION ALL
SELECT u.BTCH_ID, u.Batch_Dt, u.AUTHZN_ID, u.SRC_DATA_KEY, u.Case_Key, u.Functional_Area, u.Determination, u.Processing, u.Sample_Status, 'Determination date missing or not a date' AS Issue_Txt, 'Error' AS Severity_Txt, 'DETRMTN_NOTFTN_DT' AS Column_Nm, CAST(u.DETRMTN_NOTFTN_DT AS VARCHAR(500)) AS Value_Txt, 1 AS Issue_Cnt FROM HSLABBOSS.V_SMPL_DSH_UNIVERSE u WHERE u.DQ_Bad_Determination_Date = 1
UNION ALL
SELECT u.BTCH_ID, u.Batch_Dt, u.AUTHZN_ID, u.SRC_DATA_KEY, u.Case_Key, u.Functional_Area, u.Determination, u.Processing, u.Sample_Status, 'Determination date before the request date' AS Issue_Txt, 'Error' AS Severity_Txt, 'DETRMTN_NOTFTN_DT' AS Column_Nm, CAST(u.DETRMTN_NOTFTN_DT AS VARCHAR(500)) AS Value_Txt, 1 AS Issue_Cnt FROM HSLABBOSS.V_SMPL_DSH_UNIVERSE u WHERE u.DQ_Notice_Before_Request = 1
UNION ALL
SELECT u.BTCH_ID, u.Batch_Dt, u.AUTHZN_ID, u.SRC_DATA_KEY, u.Case_Key, u.Functional_Area, u.Determination, u.Processing, u.Sample_Status, 'Denial without the medical necessity indicator' AS Issue_Txt, 'Warning' AS Severity_Txt, 'REQ_DENY_FOR_LACK_OF_MED_NECTY_IND' AS Column_Nm, CAST(u.REQ_DENY_FOR_LACK_OF_MED_NECTY_IND AS VARCHAR(500)) AS Value_Txt, 1 AS Issue_Cnt FROM HSLABBOSS.V_SMPL_DSH_UNIVERSE u WHERE u.DQ_Denial_Missing_MedNec = 1
UNION ALL
SELECT u.BTCH_ID, u.Batch_Dt, u.AUTHZN_ID, u.SRC_DATA_KEY, u.Case_Key, u.Functional_Area, u.Determination, u.Processing, u.Sample_Status, 'Denial without a member written notification date' AS Issue_Txt, 'Warning' AS Severity_Txt, 'MBR_WRTN_NOTFTN_DT' AS Column_Nm, CAST(u.MBR_WRTN_NOTFTN_DT AS VARCHAR(500)) AS Value_Txt, 1 AS Issue_Cnt FROM HSLABBOSS.V_SMPL_DSH_UNIVERSE u WHERE u.DQ_Denial_Missing_Written_Notice = 1
UNION ALL
SELECT u.BTCH_ID, u.Batch_Dt, u.AUTHZN_ID, u.SRC_DATA_KEY, u.Case_Key, u.Functional_Area, u.Determination, u.Processing, u.Sample_Status, 'The same AUTHZN_ID and SRC_DATA_KEY more than once in the batch' AS Issue_Txt, 'Error' AS Severity_Txt, 'AUTHZN_ID' AS Column_Nm, CAST(u.AUTHZN_ID AS VARCHAR(500)) AS Value_Txt, 1 AS Issue_Cnt FROM HSLABBOSS.V_SMPL_DSH_UNIVERSE u WHERE u.DQ_Duplicate_Key = 1;

-- V_SMPL_DSH_SAMPLE: The current sample of every cycle (the target table) with the case attributes, its status and its stratum weight
REPLACE VIEW HSLABBOSS.V_SMPL_DSH_SAMPLE AS
LOCKING ROW FOR ACCESS
SELECT b.BTCH_ID, b.AUTHZN_ID, b.SRC_DATA_KEY, b.MBR_ID, b.CNTRCT_NUM, b.PBP_NUM, b.FDR_NM, b.AUTHZN_REQ_DT, b.DETRMTN_NOTFTN_DT, b.MBR_WRTN_NOTFTN_DT, b.AUTHZN_REQ_DETRMTN_TY, b.AUTHZN_REQ_STD_OR_EXPDT_IND, b.AUTHZN_REQ_EXPDT_PROCS_STD_IND, b.TIMEFRAME_EXT_IND, b.PART_B_DRUG_REQ_IND, b.REQSTR_TY_CD, b.ISS_DESC, b.REQ_DENY_FOR_LACK_OF_MED_NECTY_IND, b.SVC_CTGRY_CD, b.AUTHZN_STAT_RSN_DESC, b.WTHDRL_DESC, b.REQ_PROV_TY, b.SVC_PROV_TY, b.CPT_PROC_CD, b.RVSN_NBR, b.UNVRS_VRSN_CD, b.FILE_NM, b.SMPL_RUN_ID, b.SMPL_RUN_KEY, b.SMPL_CYCLE_DT, b.SMPL_ORDER_NBR, b.SMPL_STRATUM_PATH, 'AUTHZN_ID=' || TRIM(TRAILING FROM b.AUTHZN_ID) || '|SRC_DATA_KEY=' || TRIM(CAST(b.SRC_DATA_KEY AS VARCHAR(20))) AS Case_Key, TRYCAST(SUBSTR(b.BTCH_ID, 1, 4) || '-' || SUBSTR(b.BTCH_ID, 5, 2) || '-' || SUBSTR(b.BTCH_ID, 7, 2) AS DATE) AS Batch_Dt, CASE WHEN b.Request_Type = 'Drugs - Biologics Part B' THEN 'Part B' WHEN b.Request_Type LIKE 'Behavioral Health%' OR (b.Request_Type = 'Outpatient' AND b.Type_Detail = 'Behavioral Health') THEN 'BH' WHEN b.Request_Type = 'Outpatient' AND b.Type_Detail LIKE 'Durable Medical Equipment%' THEN 'DME' WHEN b.Request_Type = 'Outpatient' AND b.Type_Detail = 'Home Health Services' THEN 'HHC' WHEN b.Request_Type = 'Inpatient' AND (b.Type_Detail IN ('Rehab', 'LTAC') OR b.Type_Detail LIKE 'SNF%') THEN 'IP PAC' WHEN b.Request_Type = 'Outpatient' THEN 'OP Medical' WHEN b.Request_Type = 'Inpatient' THEN 'IP Medical' ELSE 'OTHER' END AS Functional_Area, CASE CASE WHEN b.Request_Type = 'Drugs - Biologics Part B' THEN 'Part B' WHEN b.Request_Type LIKE 'Behavioral Health%' OR (b.Request_Type = 'Outpatient' AND b.Type_Detail = 'Behavioral Health') THEN 'BH' WHEN b.Request_Type = 'Outpatient' AND b.Type_Detail LIKE 'Durable Medical Equipment%' THEN 'DME' WHEN b.Request_Type = 'Outpatient' AND b.Type_Detail = 'Home Health Services' THEN 'HHC' WHEN b.Request_Type = 'Inpatient' AND (b.Type_Detail IN ('Rehab', 'LTAC') OR b.Type_Detail LIKE 'SNF%') THEN 'IP PAC' WHEN b.Request_Type = 'Outpatient' THEN 'OP Medical' WHEN b.Request_Type = 'Inpatient' THEN 'IP Medical' ELSE 'OTHER' END WHEN 'DME' THEN 'OP PAC' WHEN 'HHC' THEN 'OP PAC' WHEN 'OP Medical' THEN 'Medical' WHEN 'IP Medical' THEN 'Medical' ELSE CASE WHEN b.Request_Type = 'Drugs - Biologics Part B' THEN 'Part B' WHEN b.Request_Type LIKE 'Behavioral Health%' OR (b.Request_Type = 'Outpatient' AND b.Type_Detail = 'Behavioral Health') THEN 'BH' WHEN b.Request_Type = 'Outpatient' AND b.Type_Detail LIKE 'Durable Medical Equipment%' THEN 'DME' WHEN b.Request_Type = 'Outpatient' AND b.Type_Detail = 'Home Health Services' THEN 'HHC' WHEN b.Request_Type = 'Inpatient' AND (b.Type_Detail IN ('Rehab', 'LTAC') OR b.Type_Detail LIKE 'SNF%') THEN 'IP PAC' WHEN b.Request_Type = 'Outpatient' THEN 'OP Medical' WHEN b.Request_Type = 'Inpatient' THEN 'IP Medical' ELSE 'OTHER' END END AS Area_Group, CASE WHEN CASE WHEN b.Request_Type = 'Drugs - Biologics Part B' THEN 'Part B' WHEN b.Request_Type LIKE 'Behavioral Health%' OR (b.Request_Type = 'Outpatient' AND b.Type_Detail = 'Behavioral Health') THEN 'BH' WHEN b.Request_Type = 'Outpatient' AND b.Type_Detail LIKE 'Durable Medical Equipment%' THEN 'DME' WHEN b.Request_Type = 'Outpatient' AND b.Type_Detail = 'Home Health Services' THEN 'HHC' WHEN b.Request_Type = 'Inpatient' AND (b.Type_Detail IN ('Rehab', 'LTAC') OR b.Type_Detail LIKE 'SNF%') THEN 'IP PAC' WHEN b.Request_Type = 'Outpatient' THEN 'OP Medical' WHEN b.Request_Type = 'Inpatient' THEN 'IP Medical' ELSE 'OTHER' END = 'IP PAC' THEN CASE WHEN b.Type_Detail = 'Rehab' THEN 'IPRF' WHEN b.Type_Detail = 'LTAC' THEN 'LTAC' ELSE 'SNF' END END AS IP_PAC_Type, CASE WHEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) = 'Partially Approved' THEN 'Approved' WHEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) IN ('Approved', 'Denied', 'Dismissed') THEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) WHEN COALESCE(TRIM(b.AUTHZN_REQ_DETRMTN_TY), '') = '' THEN 'Missing' ELSE 'Other' END AS Determination, CASE TRIM(b.AUTHZN_REQ_STD_OR_EXPDT_IND) WHEN 'E' THEN 'Expedited' WHEN 'S' THEN 'Standard' ELSE 'Unknown' END AS Processing, CASE WHEN UPPER(TRIM(b.SVC_PROV_TY)) = 'NON PAR' THEN 'Out of network' WHEN UPPER(TRIM(b.SVC_PROV_TY)) = 'PAR' THEN 'In network' ELSE 'Unknown' END AS Network, CASE WHEN UPPER(TRIM(b.SVC_PROV_TY)) = 'NON PAR' THEN 1 ELSE 0 END AS OON_Ind, CASE WHEN CASE WHEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) = 'Partially Approved' THEN 'Approved' WHEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) IN ('Approved', 'Denied', 'Dismissed') THEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) WHEN COALESCE(TRIM(b.AUTHZN_REQ_DETRMTN_TY), '') = '' THEN 'Missing' ELSE 'Other' END = 'Denied' AND UPPER(TRIM(b.REQ_DENY_FOR_LACK_OF_MED_NECTY_IND)) = 'Y' THEN 1 ELSE 0 END AS Med_Necessity_Denial_Ind, NULLIF(OREPLACE(COALESCE(b.CPT_PROC_CD, ''), ' ', ''), '') AS CPT_List, TRIM(STRTOK(NULLIF(OREPLACE(COALESCE(b.CPT_PROC_CD, ''), ' ', ''), ''), ',', 1)) AS CPT_First, CASE WHEN COALESCE(TRIM(b.CPT_PROC_CD), '') = '' THEN 0 ELSE CHARACTER_LENGTH(OREPLACE(b.CPT_PROC_CD, ' ', '')) - CHARACTER_LENGTH(OREPLACE(OREPLACE(b.CPT_PROC_CD, ' ', ''), ',', '')) + 1 END AS CPT_Cnt, COALESCE(sh.Auto_Approved_Ind, 0) AS Shrpa_Auto_Approved_Ind, COALESCE(sh.No_PA_Ind, 0) AS Shrpa_No_PA_Ind, COALESCE(sh.Clinical_Review_Ind, 0) AS Shrpa_Clinical_Review_Ind, CASE WHEN ',' || OREPLACE(COALESCE(b.CPT_PROC_CD, ''), ' ', '') || ',' LIKE ANY ('%,A4233,%', '%,A4234,%', '%,A4235,%', '%,A4236,%', '%,A4238,%', '%,A4239,%', '%,A4244,%', '%,A4245,%', '%,A4246,%', '%,A4247,%', '%,A4250,%', '%,A4253,%', '%,A4255,%', '%,A4256,%', '%,A4257,%', '%,A4258,%', '%,A4259,%', '%,A4271,%', '%,E0607,%', '%,E0784,%', '%,E2100,%', '%,E2101,%', '%,E2102,%', '%,E2103,%', '%,K0552,%') THEN 1 ELSE 0 END AS Diabetic_Supply_Ind, CASE WHEN TRIM(b.RVSN_NBR) = '1' THEN 1 ELSE 0 END AS Initial_Auth_Ind, CASE WHEN COALESCE(sh.Auto_Approved_Ind, 0) = 1 THEN 'AUTO_APPROVED' WHEN COALESCE(sh.No_PA_Ind, 0) = 1 THEN 'NO_PA_REQUIRED' WHEN CASE WHEN ',' || OREPLACE(COALESCE(b.CPT_PROC_CD, ''), ' ', '') || ',' LIKE ANY ('%,A4233,%', '%,A4234,%', '%,A4235,%', '%,A4236,%', '%,A4238,%', '%,A4239,%', '%,A4244,%', '%,A4245,%', '%,A4246,%', '%,A4247,%', '%,A4250,%', '%,A4253,%', '%,A4255,%', '%,A4256,%', '%,A4257,%', '%,A4258,%', '%,A4259,%', '%,A4271,%', '%,E0607,%', '%,E0784,%', '%,E2100,%', '%,E2101,%', '%,E2102,%', '%,E2103,%', '%,K0552,%') THEN 1 ELSE 0 END = 1 THEN 'DIABETIC_SUPPLIES' WHEN COALESCE(TRIM(b.RVSN_NBR), '') <> '1' THEN 'REVISION' END AS Expected_Exclusion, CASE WHEN CASE WHEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) = 'Partially Approved' THEN 'Approved' WHEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) IN ('Approved', 'Denied', 'Dismissed') THEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) WHEN COALESCE(TRIM(b.AUTHZN_REQ_DETRMTN_TY), '') = '' THEN 'Missing' ELSE 'Other' END = 'Denied' THEN 'Yes' WHEN CASE WHEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) = 'Partially Approved' THEN 'Approved' WHEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) IN ('Approved', 'Denied', 'Dismissed') THEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) WHEN COALESCE(TRIM(b.AUTHZN_REQ_DETRMTN_TY), '') = '' THEN 'Missing' ELSE 'Other' END = 'Approved' AND COALESCE(sh.Clinical_Review_Ind, 0) = 1 THEN 'Yes' ELSE 'No' END AS Needs_Clinical_Auditor, CASE WHEN CASE WHEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) = 'Partially Approved' THEN 'Approved' WHEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) IN ('Approved', 'Denied', 'Dismissed') THEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) WHEN COALESCE(TRIM(b.AUTHZN_REQ_DETRMTN_TY), '') = '' THEN 'Missing' ELSE 'Other' END = 'Denied' OR (CASE WHEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) = 'Partially Approved' THEN 'Approved' WHEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) IN ('Approved', 'Denied', 'Dismissed') THEN TRIM(b.AUTHZN_REQ_DETRMTN_TY) WHEN COALESCE(TRIM(b.AUTHZN_REQ_DETRMTN_TY), '') = '' THEN 'Missing' ELSE 'Other' END = 'Approved' AND COALESCE(sh.Clinical_Review_Ind, 0) = 1) THEN 'Clinical' ELSE 'Administrative' END AS Auditor_Type, TRYCAST(OREPLACE(TRIM(b.AUTHZN_REQ_DT), '/', '-') AS DATE) AS Request_Dt, TRYCAST(OREPLACE(TRIM(b.DETRMTN_NOTFTN_DT), '/', '-') AS DATE) AS Determination_Dt, TRYCAST(OREPLACE(TRIM(b.DETRMTN_NOTFTN_DT), '/', '-') AS DATE) - TRYCAST(OREPLACE(TRIM(b.AUTHZN_REQ_DT), '/', '-') AS DATE) AS Decision_Days, 1 AS Case_Cnt, b.Request_Type, b.Type_Detail, r.Run_Stat, r.Finalized_By, r.Finalized_Dtts, r.End_Dtts AS Run_End_Dtts, COALESCE(x.Selection_Stat, 'SELECTED') AS Selection_Stat, x.Linked_Case_Key, x.Stat_Rsn_Txt, x.Stat_By, x.Priority_Rank_Nbr, x.Bucket_Rank_Nbr, t.Candidate_Cnt AS Stratum_Candidate_Cnt, t.Selected_Cnt AS Stratum_Selected_Cnt, CASE WHEN t.Selected_Cnt > 0 THEN CAST(t.Candidate_Cnt AS DECIMAL(18,4)) / t.Selected_Cnt END AS Design_Weight, CASE WHEN t.Candidate_Cnt > 0 THEN CAST(t.Selected_Cnt AS DECIMAL(18,4)) / t.Candidate_Cnt END AS Sampling_Fraction FROM (SELECT o.BTCH_ID, o.AUTHZN_ID, o.SRC_DATA_KEY, o.MBR_ID, o.CNTRCT_NUM, o.PBP_NUM, o.FDR_NM, o.AUTHZN_REQ_DT, o.DETRMTN_NOTFTN_DT, o.MBR_WRTN_NOTFTN_DT, o.AUTHZN_REQ_DETRMTN_TY, o.AUTHZN_REQ_STD_OR_EXPDT_IND, o.AUTHZN_REQ_EXPDT_PROCS_STD_IND, o.TIMEFRAME_EXT_IND, o.PART_B_DRUG_REQ_IND, o.REQSTR_TY_CD, o.ISS_DESC, o.REQ_DENY_FOR_LACK_OF_MED_NECTY_IND, o.SVC_CTGRY_CD, o.AUTHZN_STAT_RSN_DESC, o.WTHDRL_DESC, o.REQ_PROV_TY, o.SVC_PROV_TY, o.CPT_PROC_CD, o.RVSN_NBR, o.UNVRS_VRSN_CD, o.FILE_NM, o.SMPL_RUN_ID, o.SMPL_RUN_KEY, o.SMPL_CYCLE_DT, o.SMPL_ORDER_NBR, o.SMPL_STRATUM_PATH, TRIM(STRTOK(NULLIF(TRIM(o.ISS_DESC), ''), ',', 1)) AS Request_Type, TRIM(STRTOK(NULLIF(TRIM(o.ISS_DESC), ''), ',', 2)) AS Type_Detail, COUNT(*) OVER (PARTITION BY o.BTCH_ID, o.AUTHZN_ID, o.SRC_DATA_KEY) AS Key_Row_Cnt FROM HSLABBOSS.SDO_CMPLNC_CLNCL_AUD_UM_AUTHZN_ODAG1_Sample o WHERE o.ETL_IS_CURR_IND = 'Y') b LEFT JOIN (SELECT o2.BTCH_ID, o2.AUTHZN_ID, o2.SRC_DATA_KEY, MAX(CASE WHEN s.IS_Auth_Required LIKE '%approve%' THEN 1 ELSE 0 END) AS Auto_Approved_Ind, MAX(CASE WHEN s.IS_Auth_Required = 'No Auth Required - Check to see if a global rule applies' THEN 1 ELSE 0 END) AS No_PA_Ind, MAX(CASE WHEN COALESCE(TRIM(s.Clinical_Mgt_Route), '') <> '' THEN 1 ELSE 0 END) AS Clinical_Review_Ind FROM HSLABBOSS.SDO_CMPLNC_CLNCL_AUD_UM_AUTHZN_ODAG1_Sample o2 JOIN HSLABBOSS.UMCM_SHRPA_PROCEDURE_CODES s ON POSITION(',' || TRIM(s.PROCEDURE_CODE) || ',' IN ',' || OREPLACE(COALESCE(o2.CPT_PROC_CD, ''), ' ', '') || ',') > 0 AND s.ETL_IS_CURR_IND = 'Y' AND s.ETL_IS_DEL_IND = 'N' WHERE o2.ETL_IS_CURR_IND = 'Y' GROUP BY 1, 2, 3) sh ON sh.BTCH_ID = b.BTCH_ID AND sh.AUTHZN_ID = b.AUTHZN_ID AND sh.SRC_DATA_KEY = b.SRC_DATA_KEY JOIN HSLABBOSS.GOVT_RGLTRY_SamplingRun r ON r.Smpl_Run_ID = b.SMPL_RUN_ID AND r.Curr_Ind = 1 LEFT JOIN HSLABBOSS.GOVT_RGLTRY_SampleSelection x ON x.Smpl_Run_ID = b.SMPL_RUN_ID AND x.Case_Key = 'AUTHZN_ID=' || TRIM(TRAILING FROM b.AUTHZN_ID) || '|SRC_DATA_KEY=' || TRIM(CAST(b.SRC_DATA_KEY AS VARCHAR(20))) LEFT JOIN HSLABBOSS.GOVT_RGLTRY_SamplingRunStat t ON t.Smpl_Run_ID = b.SMPL_RUN_ID AND t.Stat_Ty = 'BUCKET' AND t.Stat_Nm = b.SMPL_STRATUM_PATH;

-- V_SMPL_DSH_RUN: Every run: counts, timing, reruns, overrides, errors, configuration changes
REPLACE VIEW HSLABBOSS.V_SMPL_DSH_RUN AS
LOCKING ROW FOR ACCESS
SELECT r.Smpl_Run_ID, r.Project_Cd, r.Table_Nm, r.Run_Ty, r.Run_Key, r.As_Of_Dt_Key, r.Run_Stat, r.Curr_Ind, r.Random_Seed_Nbr, r.In_Scope_Cnt, r.Excluded_Cnt, r.Candidate_Cnt, r.Selected_Cnt, r.Shortfall_Cnt, r.Target_Cnt, r.Error_Ty, r.Error_Txt, r.Override_Rsn_Txt, r.Rerun_Rsn_Txt, r.Rules_As_Of_Dt, r.Finalized_By, r.Finalized_Dtts, r.Triggered_By, r.Start_Dtts, r.End_Dtts, r.Config_Hash, r.Smpl_Method_Cd, CAST(((CAST(r.End_Dtts AS DATE) - DATE '2000-01-01') * 86400 + EXTRACT(HOUR FROM r.End_Dtts) * 3600 + EXTRACT(MINUTE FROM r.End_Dtts) * 60 + EXTRACT(SECOND FROM r.End_Dtts) - (CAST(r.Start_Dtts AS DATE) - DATE '2000-01-01') * 86400 + EXTRACT(HOUR FROM r.Start_Dtts) * 3600 + EXTRACT(MINUTE FROM r.Start_Dtts) * 60 + EXTRACT(SECOND FROM r.Start_Dtts)) / 60.0 AS DECIMAL(12,2)) AS Duration_Min, CASE TD_DAY_OF_WEEK(CAST(r.Start_Dtts AS DATE)) WHEN 1 THEN 'Sun' WHEN 2 THEN 'Mon' WHEN 3 THEN 'Tue' WHEN 4 THEN 'Wed' WHEN 5 THEN 'Thu' WHEN 6 THEN 'Fri' ELSE 'Sat' END AS Run_Weekday, EXTRACT(HOUR FROM r.Start_Dtts) AS Start_Hour, CASE WHEN r.Rerun_Rsn_Txt IS NOT NULL THEN 1 ELSE 0 END AS Rerun_Ind, CASE WHEN r.Override_Rsn_Txt IS NOT NULL THEN 1 ELSE 0 END AS Override_Ind, CASE WHEN r.Run_Stat = 'FINAL' THEN 1 ELSE 0 END AS Finalized_Ind, CASE WHEN r.Run_Stat IN ('ERROR', 'FAILED') THEN 1 ELSE 0 END AS Failed_Ind, CASE WHEN r.Run_Stat IN ('COMPLETED', 'FINAL') THEN 1 ELSE 0 END AS Completed_Ind, CASE WHEN r.Shortfall_Cnt > 0 THEN 1 ELSE 0 END AS Shortfall_Ind, MAX(r.Config_Hash) OVER (PARTITION BY r.Project_Cd, r.Table_Nm, r.Run_Ty ORDER BY r.Start_Dtts ROWS BETWEEN 1 PRECEDING AND 1 PRECEDING) AS Prior_Config_Hash, CASE WHEN r.Curr_Ind = 1 THEN 'Current' ELSE 'Replaced by a rerun' END AS Run_Version, CASE WHEN r.Override_Rsn_Txt IS NOT NULL THEN 'Override' WHEN r.Rerun_Rsn_Txt IS NOT NULL THEN 'Rerun' ELSE 'First run' END AS Run_Kind, 1 AS Run_Cnt, CASE WHEN r.Config_Hash <> MAX(r.Config_Hash) OVER (PARTITION BY r.Project_Cd, r.Table_Nm, r.Run_Ty ORDER BY r.Start_Dtts ROWS BETWEEN 1 PRECEDING AND 1 PRECEDING) THEN 1 ELSE 0 END AS Config_Changed_Ind FROM HSLABBOSS.GOVT_RGLTRY_SamplingRun r;

-- V_SMPL_DSH_RUN_STAT: The figures of every completed run: buckets, caps, exclusions, rules
REPLACE VIEW HSLABBOSS.V_SMPL_DSH_RUN_STAT AS
LOCKING ROW FOR ACCESS
SELECT t.Smpl_Run_ID, t.Project_Cd, t.Table_Nm, t.Run_Ty, t.Run_Key, t.As_Of_Dt_Key, t.Stat_Ty, t.Stat_Seq_Nbr, t.Stat_Nm, t.Rule_ID, t.Leaf_Ind, t.Candidate_Cnt, t.Target_Cnt, t.Selected_Cnt, t.Limit_Cnt, t.Over_Cnt, t.Replaced_Cnt, t.Case_Cnt, t.Stat_Txt, r.Curr_Ind AS Run_Curr_Ind, r.Run_Stat AS Run_Stat, r.Start_Dtts AS Run_Start_Dtts, CASE WHEN t.Stat_Ty = 'BUCKET' THEN CHARACTER_LENGTH(t.Stat_Nm) - CHARACTER_LENGTH(OREPLACE(t.Stat_Nm, '/', '')) + 1 END AS Path_Depth, CASE WHEN t.Stat_Ty = 'BUCKET' THEN STRTOK(t.Stat_Nm, '/', 1) END AS Path_Level_1, CASE WHEN t.Stat_Ty = 'BUCKET' THEN STRTOK(t.Stat_Nm, '/', 2) END AS Path_Level_2, CASE WHEN t.Stat_Ty = 'BUCKET' THEN STRTOK(t.Stat_Nm, '/', 3) END AS Path_Level_3, CASE WHEN t.Stat_Ty = 'BUCKET' AND t.Target_Cnt > t.Selected_Cnt THEN t.Target_Cnt - t.Selected_Cnt ELSE 0 END AS Bucket_Shortfall_Cnt, CASE WHEN t.Stat_Ty = 'BUCKET' AND t.Candidate_Cnt > 0 THEN CAST(t.Selected_Cnt AS DECIMAL(18,4)) / t.Candidate_Cnt END AS Sampling_Fraction, CASE WHEN t.Stat_Ty = 'BUCKET' AND t.Leaf_Ind = 1 THEN 'Leaf bucket' WHEN t.Stat_Ty = 'BUCKET' THEN 'Parent bucket' ELSE t.Stat_Ty END AS Stat_Kind, CASE WHEN t.Stat_Ty = 'BUCKET' AND t.Leaf_Ind = 1 THEN t.Target_Cnt ELSE 0 END AS Leaf_Target_Cnt, CASE WHEN t.Stat_Ty = 'BUCKET' AND t.Leaf_Ind = 1 THEN t.Selected_Cnt ELSE 0 END AS Leaf_Selected_Cnt, CASE WHEN t.Stat_Ty = 'BUCKET' AND t.Leaf_Ind = 1 THEN t.Candidate_Cnt ELSE 0 END AS Leaf_Candidate_Cnt FROM HSLABBOSS.GOVT_RGLTRY_SamplingRunStat t JOIN HSLABBOSS.GOVT_RGLTRY_SamplingRun r ON r.Smpl_Run_ID = t.Smpl_Run_ID AND r.Curr_Ind = 1;

-- V_SMPL_DSH_REVAL: Revalidations (8.01) and their sign-off
REPLACE VIEW HSLABBOSS.V_SMPL_DSH_REVAL AS
LOCKING ROW FOR ACCESS
SELECT v.Reval_ID, v.Smpl_Run_ID, v.Project_Cd, v.Table_Nm, v.Run_Ty, v.Run_Key, v.As_Of_Dt_Key, v.Source_As_Of_Dtts, v.Reval_Dtts, v.Triggered_By, v.Reval_Stat, v.Orig_Selected_Cnt, v.Replay_Selected_Cnt, v.Same_Cnt, v.Only_Orig_Cnt, v.Only_Replay_Cnt, v.Missing_Cnt, v.Diff_Txt, v.Engine_Version_Txt, v.Error_Txt, v.Signoff_By, v.Signoff_Dtts, v.Signoff_Txt, CASE WHEN v.Signoff_By IS NULL THEN 'Waiting' ELSE 'Signed off' END AS Signed_Off, CASE WHEN v.Reval_Stat = 'MATCH' THEN 1 ELSE 0 END AS Match_Ind, CAST(v.Signoff_Dtts AS DATE) - CAST(v.Reval_Dtts AS DATE) AS Days_To_Signoff, 1 AS Reval_Cnt FROM HSLABBOSS.GOVT_RGLTRY_SamplingRevalidation v;

-- V_SMPL_DSH_REFINE: Refinement findings and totals (8.03) and their review
REPLACE VIEW HSLABBOSS.V_SMPL_DSH_REFINE AS
LOCKING ROW FOR ACCESS
SELECT f.Refine_ID, f.Finding_Seq_Nbr, f.Project_Cd, f.Table_Nm, f.Run_Ty, f.Window_Start_Dt, f.Window_End_Dt, f.Run_Cnt, f.Finding_Ty, f.Finding_Nm, f.Rule_ID, f.Short_Run_Cnt, f.Missing_Cnt, f.Blocked_Cnt, f.Lost_Cnt, f.Case_Cnt, f.Prior_Avg_Val, f.Last_As_Of_Dt, f.Finding_Txt, f.Threshold_Txt, f.Report_Dtts, f.Review_By, f.Review_Dtts, f.Review_Txt, CASE WHEN f.Finding_Ty IN ('NOT_PICKED', 'TOPUP', 'REPLACED') THEN 'Total' ELSE 'Finding' END AS Row_Kind, CASE WHEN f.Review_By IS NULL THEN 'Open' ELSE 'Reviewed' END AS Review_Status, 1 AS Finding_Cnt FROM HSLABBOSS.GOVT_RGLTRY_SamplingRefinement f;

-- V_SMPL_DSH_RULE: The rules of the UMCM samples, with whether each is in effect today
REPLACE VIEW HSLABBOSS.V_SMPL_DSH_RULE AS
LOCKING ROW FOR ACCESS
SELECT g.Rule_ID, g.Project_Cd, g.Table_Nm, g.Run_Ty, g.Rule_Class_Cd, g.Seq_Nbr, g.Rule_Nm, g.Rule_Ty, g.Level_Nbr, g.Parent_Path_Txt, g.Quota_Cd, g.Quota_Val, g.Max_Ty, g.Max_Val, g.Lookback_Days, g.History_Scope_Cd, g.Rule_Desc, g.Active_Ind, g.Eff_Start_Dt, g.Eff_End_Dt, g.Rule_Sql_Txt, CASE WHEN g.Active_Ind = 1 AND CURRENT_DATE BETWEEN g.Eff_Start_Dt AND g.Eff_End_Dt THEN 'In effect' ELSE 'Not in effect' END AS In_Effect, 1 AS Rule_Cnt FROM HSLABBOSS.GOVT_RGLTRY_SamplingRule g WHERE g.Project_Cd IN ('UMCM', '*');

-- V_SMPL_DSH_BATCH: Framework batches of the sample and whether each was sampled
REPLACE VIEW HSLABBOSS.V_SMPL_DSH_BATCH AS
LOCKING ROW FOR ACCESS
SELECT c.Project_Cd, c.Table_Nm, c.Run_Ty, c.Btch_ID, c.Source_Cnt, c.Closed_Source_Cnt, CASE WHEN c.Closed_Source_Cnt = c.Source_Cnt THEN 'Closed' ELSE 'Open' END AS Batch_Status, TRYCAST(SUBSTR(c.Btch_ID, 1, 4) || '-' || SUBSTR(c.Btch_ID, 5, 2) || '-' || SUBSTR(c.Btch_ID, 7, 2) AS DATE) AS Batch_Dt, r.Smpl_Run_ID, r.Run_Stat, r.Start_Dtts, r.End_Dtts, r.Selected_Cnt, CASE WHEN r.Smpl_Run_ID IS NULL THEN 'Not sampled' ELSE 'Sampled' END AS Sampled_Status, 1 AS Batch_Cnt FROM (SELECT Project_Cd, Table_Nm, Run_Ty, Btch_ID, COUNT(*) AS Source_Cnt, SUM(CASE WHEN Batch_Close_Ind = 1 THEN 1 ELSE 0 END) AS Closed_Source_Cnt FROM HSLABBOSS.GOVT_RGLTRY_RequestControl WHERE Project_Cd = 'UMCM' AND Table_Nm = 'ODAG1' AND Run_Ty = 'WKLY' GROUP BY 1, 2, 3, 4) c LEFT JOIN HSLABBOSS.GOVT_RGLTRY_SamplingRun r ON r.Project_Cd = 'UMCM' AND r.Table_Nm = 'ODAG1' AND r.Run_Ty = 'WKLY' AND r.Curr_Ind = 1 AND r.Run_Key = c.Btch_ID;

-- V_SMPL_DSH_RETENTION: Rows kept per object and year (6.01, 6.02)
REPLACE VIEW HSLABBOSS.V_SMPL_DSH_RETENTION AS
LOCKING ROW FOR ACCESS
SELECT CAST('Universe (source rows, every version)' AS VARCHAR(60)) AS Object_Nm, CAST(EXTRACT(YEAR FROM ETL_LOAD_DT_TM) AS INTEGER) AS Data_Year, CAST(COUNT(*) AS BIGINT) AS Row_Cnt FROM HSLABBOSS.SDO_CMPLNC_CLNCL_AUD_UM_AUTHZN_ODAG1 GROUP BY 1, 2
UNION ALL
SELECT CAST('Sample (target rows)' AS VARCHAR(60)) AS Object_Nm, CAST(EXTRACT(YEAR FROM SMPL_CYCLE_DT) AS INTEGER) AS Data_Year, CAST(COUNT(*) AS BIGINT) AS Row_Cnt FROM HSLABBOSS.SDO_CMPLNC_CLNCL_AUD_UM_AUTHZN_ODAG1_Sample GROUP BY 1, 2
UNION ALL
SELECT CAST('Sample runs' AS VARCHAR(60)) AS Object_Nm, CAST(EXTRACT(YEAR FROM As_Of_Dt_Key) AS INTEGER) AS Data_Year, CAST(COUNT(*) AS BIGINT) AS Row_Cnt FROM HSLABBOSS.GOVT_RGLTRY_SamplingRun GROUP BY 1, 2
UNION ALL
SELECT CAST('Selection rows (candidates)' AS VARCHAR(60)) AS Object_Nm, CAST(EXTRACT(YEAR FROM Smpl_Cycle_Dt_Key) AS INTEGER) AS Data_Year, CAST(COUNT(*) AS BIGINT) AS Row_Cnt FROM HSLABBOSS.GOVT_RGLTRY_SampleSelection GROUP BY 1, 2
UNION ALL
SELECT CAST('Run figures' AS VARCHAR(60)) AS Object_Nm, CAST(EXTRACT(YEAR FROM As_Of_Dt_Key) AS INTEGER) AS Data_Year, CAST(COUNT(*) AS BIGINT) AS Row_Cnt FROM HSLABBOSS.GOVT_RGLTRY_SamplingRunStat GROUP BY 1, 2
UNION ALL
SELECT CAST('Revalidations' AS VARCHAR(60)) AS Object_Nm, CAST(EXTRACT(YEAR FROM As_Of_Dt_Key) AS INTEGER) AS Data_Year, CAST(COUNT(*) AS BIGINT) AS Row_Cnt FROM HSLABBOSS.GOVT_RGLTRY_SamplingRevalidation GROUP BY 1, 2
UNION ALL
SELECT CAST('Refinement rows' AS VARCHAR(60)) AS Object_Nm, CAST(EXTRACT(YEAR FROM Window_End_Dt) AS INTEGER) AS Data_Year, CAST(COUNT(*) AS BIGINT) AS Row_Cnt FROM HSLABBOSS.GOVT_RGLTRY_SamplingRefinement GROUP BY 1, 2;
